import * as THREE from 'three';
import{createAudio}from'./audio.js';
import{WORLD,makeCity}from'./world.js';import{JOBS}from'./missions.js';
const audio=createAudio();const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),start=document.querySelector('#start');let W,H,scale=1;function resize(){W=canvas.width=innerWidth*devicePixelRatio;H=canvas.height=innerHeight*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);W=innerWidth;H=innerHeight}resize();addEventListener('resize',resize);
const city=makeCity(),player={x:320,y:320,angle:0,hp:100,cash:500,stars:0,car:null,speed:0,ammo:36,jump:0};let keys={},mouse={x:W/2,y:H/2},mission=0,active=false,paused=false,mute=false,heat=0,feedback=0,muzzle=0,last=performance.now(),shots=[],dust=[];const police=[],officers=[],camera={x:320,y:320};const mapSize=152;
try{const s=JSON.parse(localStorage.getItem('marisol-save')||'{}');if(s.cash)player.cash=s.cash;if(s.mission)mission=s.mission;if(s.x){player.x=s.x;player.y=s.y}}catch{}
function save(){try{localStorage.setItem('marisol-save',JSON.stringify({cash:player.cash,mission,x:player.x,y:player.y}))}catch{}}
function crime(n=1){player.stars=Math.min(5,player.stars+Math.ceil(n));heat=18;feedback=1;for(let i=0;i<player.stars;i++)if(!police[i])police.push({x:player.x+(i+1)*160,y:player.y+(i%2?180:-180),speed:0});if(player.stars>=3&&!officers.length)officers.push({x:player.x-150,y:player.y+110})}
function nearestCar(){return city.cars.reduce((best,c)=>Math.hypot(c.x-player.x,c.y-player.y)<Math.hypot((best?.x??1e5)-player.x,(best?.y??1e5)-player.y)?c:best,null)}
function toggleCar(){if(player.car){audio.tone(330);player.car.occupied=false;player.x=player.car.x+40;player.y=player.car.y+20;player.car=null;player.speed=0;return}let c=nearestCar();if(c&&Math.hypot(c.x-player.x,c.y-player.y)<75){player.car=c;c.occupied=true;audio.tone(620);player.angle=c.angle;if(!c.parked)crime(1);else if(!c.stolen){crime(1);c.stolen=true}}}
function startGame(){active=true;audio.start();start.style.display='none';canvas.requestPointerLock?.();}
document.querySelector('#begin').onclick=startGame;addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyE')toggleCar();if(e.code==='KeyM'){mute=!mute;audio.toggle();}if(e.code==='Escape'&&active)paused=!paused;if(e.code==='Space'&&!player.car)player.jump=.45});addEventListener('keyup',e=>keys[e.code]=false);addEventListener('mousemove',e=>{mouse.x=e.clientX;mouse.y=e.clientY;if(document.pointerLockElement===canvas)player.angle+=e.movementX*.0025});canvas.addEventListener('click',()=>{if(!active)return;const angle=player.angle;shots.push({x:player.x+Math.cos(angle)*16,y:player.y+Math.sin(angle)*16,a:angle,t:.5});muzzle=.09;player.ammo--;crime(.2);audio.tone(110,.06)});
function worldToScreen(x,y,cx,cy){const offset=new THREE.Vector2(x-cx,y-cy);return{x:W/2+offset.x,y:H/2+offset.y}}function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(x,y,w,h)}
function drawCar(c,cx,cy){let p=worldToScreen(c.x,c.y,cx,cy);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(c.angle);rect(-23,-12,46,24,c.police?'#172b3b':c.color);rect(-11,-9,20,18,'#91b9b4');rect(-20,-15,9,4,'#242a2e');rect(11,-15,9,4,'#242a2e');rect(-20,11,9,4,'#242a2e');rect(11,11,9,4,'#242a2e');if(c.police){rect(-5,-14,10,4,'#e95651');rect(3,-14,8,4,'#65c8ef')}ctx.restore()}
function drawWorld(now){let cx=player.x,cy=player.y;if(player.car){cx+=Math.cos(player.angle)*120;cy+=Math.sin(player.angle)*120}camera.x+=(cx-camera.x)*.12;camera.y+=(cy-camera.y)*.12;cx=camera.x;cy=camera.y;rect(0,0,W,H,'#76b4ad');ctx.save();ctx.translate(W/2-cx,H/2-cy);
// coastal sand and water edge
rect(1770,0,630,2400,'#56a8b2');rect(1748,0,24,2400,'#dfc28a');rect(1850,130,320,60,'#d4b078');rect(2110,120,24,420,'#9b7958');rect(2150,380,180,16,'#b39268');
// street grid
for(let q=0;q<8;q++){const z=100+q*300;rect(z-52,0,104,2400,'#3a4748');rect(0,z-52,2400,104,'#3a4748');rect(z-2,0,4,2400,'#c7b77e');rect(0,z-2,2400,4,'#c7b77e');for(let n=0;n<2400;n+=90){rect(z-42,n,4,26,'#e5d9a5');rect(n,z-42,26,4,'#e5d9a5')}}
rect(1780,0,620,2400,'#e4cb91');
for(const b of city.buildings){rect(b.x+8,b.y+12,b.w,b.h,'#58605a');rect(b.x,b.y-b.height*.18,b.w,b.h,b.color);rect(b.x,b.y-b.height*.18,b.w,8,'#f5d291');for(let wx=b.x+12;wx<b.x+b.w-8;wx+=22)for(let wy=b.y+12;wy<b.y+b.h-12;wy+=24)rect(wx,wy-b.height*.18,9,10,'#a9c8bd')}
for(const l of city.lamps){ctx.fillStyle='#e3d39a';ctx.beginPath();ctx.arc(l.x,l.y,5,0,7);ctx.fill()}for(const t of city.palm){ctx.fillStyle='#6f5134';ctx.fillRect(t.x-3,t.y-4,6,30);ctx.fillStyle='#267b5d';ctx.beginPath();ctx.arc(t.x,t.y,19,0,7);ctx.fill()}
for(const c of city.cars)drawCar(c,cx,cy);for(const c of police)drawCar({...c,angle:Math.atan2(player.y-c.y,player.x-c.x),color:'#1c3442',police:true},cx,cy);for(const o of officers){const p=worldToScreen(o.x,o.y,cx,cy);ctx.fillStyle='#203849';ctx.beginPath();ctx.arc(p.x,p.y,9,0,7);ctx.fill();ctx.fillStyle='#81c5d4';ctx.fillRect(p.x-8,p.y-5,16,10);ctx.fillStyle='#182a36';ctx.fillRect(p.x-7,p.y-11,14,5)}
for(const p of city.people)if(p.alive){const x=p.x+Math.sin(now/700+p.phase)*13,y=p.y+Math.cos(now/800+p.phase)*11;ctx.fillStyle='#283c3c';ctx.beginPath();ctx.ellipse(x,y+7,6,9,0,0,7);ctx.fill();ctx.fillStyle=p.shirt;ctx.beginPath();ctx.arc(x,y-2,6,0,7);ctx.fill()}
// player, vehicle occupants, mission beacon
if(mission<JOBS.length){const j=JOBS[mission];ctx.strokeStyle='#ffe07b';ctx.lineWidth=5;ctx.beginPath();ctx.arc(j.x,j.y,24+Math.sin(now/190)*6,0,7);ctx.stroke();ctx.fillStyle='#ffe07b';ctx.font='bold 16px Arial';ctx.fillText('◆',j.x-8,j.y-30)}
if(!player.car){ctx.save();ctx.translate(player.x,player.y-player.jump*70);ctx.rotate(player.angle);ctx.fillStyle='#1b3237';ctx.beginPath();ctx.ellipse(1,10,10,5,0,0,7);ctx.fill();ctx.fillStyle='#d8a078';ctx.beginPath();ctx.arc(0,0,9,0,7);ctx.fill();ctx.fillStyle='#243b4b';ctx.fillRect(-8,-2,16,17);if(muzzle>0){ctx.fillStyle='#ffd978';ctx.beginPath();ctx.arc(15,0,5+Math.random()*3,0,7);ctx.fill()}ctx.restore()}
for(const d of dust){const p=worldToScreen(d.x,d.y,cx,cy);ctx.fillStyle=`rgba(224,207,161,${Math.max(0,d.t)*.45})`;ctx.beginPath();ctx.arc(p.x,p.y,7+(1-d.t)*12,0,7);ctx.fill()}for(const s of shots){ctx.fillStyle='#ffd57d';ctx.beginPath();ctx.arc(s.x,s.y,4,0,7);ctx.fill()}ctx.restore();}
function hud(){// readable compact panels
ctx.fillStyle='#102b30e8';ctx.fillRect(22,22,294,108);ctx.fillStyle='#f2c47b';ctx.font='bold 18px Arial';ctx.fillText('DARIO VOSS',38,49);ctx.fillStyle='#e8ede4';ctx.font='14px Arial';ctx.fillText(`CASH  $${player.cash.toLocaleString()}     AMMO  ${player.ammo}`,38,73);ctx.fillStyle='#475b55';ctx.fillRect(38,88,240,12);ctx.fillStyle=player.hp>35?'#79c18e':'#df634e';ctx.fillRect(38,88,240*player.hp/100,12);ctx.fillStyle='#fff';ctx.font='16px Arial';ctx.fillText('HEALTH',38,119);
ctx.fillStyle='#f3c57c';ctx.font='bold 24px Arial';ctx.fillText('★'.repeat(Math.floor(player.stars))+'☆'.repeat(5-Math.floor(player.stars)),W-190,48);ctx.fillStyle='#102b30e8';ctx.fillRect(W/2-245,22,490,72);ctx.fillStyle='#f0c47e';ctx.font='bold 13px Arial';ctx.fillText(mission<JOBS.length?JOBS[mission].name:'DEBT CLEARED',W/2-228,45);ctx.fillStyle='#fff';ctx.font='15px Arial';ctx.fillText(mission<JOBS.length?JOBS[mission].objective:'Free roam across Marisol Bay',W/2-228,71);
if(player.car){ctx.fillStyle='#102b30e8';ctx.fillRect(24,H-75,180,48);ctx.fillStyle='#f6d37f';ctx.font='bold 24px Arial';ctx.fillText(`${Math.abs(Math.round(player.speed*0.38))} km/h`,42,H-43)}
// minimap
const mx=W-mapSize-24,my=H-mapSize-24;ctx.fillStyle='#122c30ed';ctx.fillRect(mx-8,my-8,mapSize+16,mapSize+16);ctx.save();ctx.beginPath();ctx.rect(mx,my,mapSize,mapSize);ctx.clip();ctx.fillStyle='#a2b89a';ctx.fillRect(mx,my,mapSize,mapSize);const unit=mapSize/WORLD.size;for(let q=100;q<2400;q+=300){ctx.fillStyle='#475354';ctx.fillRect(mx+(q-52)*unit,my,104*unit,mapSize);ctx.fillRect(mx,my+(q-52)*unit,mapSize,104*unit)}ctx.fillStyle='#52a6ad';ctx.fillRect(mx+1770*unit,my,630*unit,mapSize);for(const c of city.cars){ctx.fillStyle=c.police?'#f45e56':'#334e4d';ctx.fillRect(mx+c.x*unit-1,my+c.y*unit-1,3,3)}for(const p of police){ctx.fillStyle='#ff665d';ctx.fillRect(mx+p.x*unit-2,my+p.y*unit-2,5,5)}if(mission<JOBS.length){ctx.fillStyle='#ffe07b';ctx.beginPath();ctx.arc(mx+JOBS[mission].x*unit,my+JOBS[mission].y*unit,4,0,7);ctx.fill()}ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(mx+player.x*unit,my+player.y*unit,4,0,7);ctx.fill();ctx.restore();ctx.fillStyle='#f2d18a';ctx.font='bold 10px Arial';ctx.fillText('MARISOL BAY',mx,my-12);
if(feedback>0){ctx.fillStyle=`rgba(220,65,48,${feedback*.25})`;ctx.fillRect(0,0,W,H)}if(paused||!active){ctx.fillStyle='#0b2020a8';ctx.fillRect(0,0,W,H);ctx.fillStyle='#fff';ctx.font='bold 34px Arial';ctx.textAlign='center';ctx.fillText(paused?'PAUSED':'MARISOL BAY',W/2,H/2);ctx.font='16px Arial';ctx.fillText('Esc to resume',W/2,H/2+32);ctx.textAlign='left'}}
function update(dt,now){if(!active||paused)return;if(document.pointerLockElement!==canvas)player.angle=Math.atan2(mouse.y-H/2,mouse.x-W/2);const forward=(keys.KeyW?1:0)-(keys.KeyS?1:0),turn=(keys.KeyD?1:0)-(keys.KeyA?1:0);if(player.car){const c=player.car;player.speed+=(forward*330-turn*100)*dt;player.speed*=Math.pow(keys.Space?.91:.985,dt*60);player.speed=Math.max(-160,Math.min(390,player.speed));player.angle+=turn*dt*(.9+Math.abs(player.speed)/160);const ox=c.x,oy=c.y;c.x+=Math.cos(player.angle)*player.speed*dt;c.y+=Math.sin(player.angle)*player.speed*dt;c.x=Math.max(40,Math.min(2360,c.x));c.y=Math.max(40,Math.min(2360,c.y));player.x=c.x;player.y=c.y;if(Math.abs(player.speed)>210&&Math.random()<.018)crime(.08);if(Math.abs(player.speed)>90&&Math.random()<.25)dust.push({x:c.x-Math.cos(player.angle)*25,y:c.y-Math.sin(player.angle)*25,t:.45});for(const p of city.people)if(p.alive&&Math.hypot(p.x-c.x,p.y-c.y)<28&&Math.abs(player.speed)>80){p.alive=false;crime(1);player.speed*=.7;player.hp=Math.max(0,player.hp-8)}if(Math.hypot(ox-c.x,oy-c.y)>2){} }
else{player.speed=0;player.angle+=turn*dt*2.5;const f=forward*(keys.ShiftLeft?190:120);player.x+=Math.cos(player.angle)*f*dt;player.y+=Math.sin(player.angle)*f*dt;player.x=Math.max(20,Math.min(2380,player.x));player.y=Math.max(20,Math.min(2380,player.y));if(player.jump>0)player.jump=Math.max(0,player.jump-dt)}
// traffic follows seeded road corridors
for(const c of city.cars)if(!c.parked&&!c.occupied){c.x+=Math.cos(c.angle)*58*dt;c.y+=Math.sin(c.angle)*58*dt;if(c.x<60||c.x>2340||c.y<60||c.y>2340)c.angle+=Math.PI/2;if(Math.random()<.005)c.angle+=Math.PI/2}
for(const o of officers){const a=Math.atan2(player.y-o.y,player.x-o.x);o.x+=Math.cos(a)*118*dt;o.y+=Math.sin(a)*118*dt;if(Math.hypot(player.x-o.x,player.y-o.y)<22&&Math.abs(player.speed)<80){player.stars=0;police.length=0;officers.length=0;player.cash=Math.max(0,player.cash-100);feedback=.8}}for(const p of police){const a=Math.atan2(player.y-p.y,player.x-p.x),d=Math.hypot(player.x-p.x,player.y-p.y);p.x+=Math.cos(a)*Math.min(195,100+d*.03)*dt;p.y+=Math.sin(a)*Math.min(195,100+d*.03)*dt;if(d<35){if(Math.abs(player.speed)<75||!player.car){player.hp-=10*dt;if(player.hp<=0){player.hp=100;player.cash=Math.max(0,player.cash-250);player.stars=0;player.x=320;player.y=320;player.car=null}}else{player.speed*=.78;player.hp=Math.max(0,player.hp-4*dt)}}}
audio.setWanted(player.stars);if(heat>0)heat-=dt;else if(player.stars&&Math.hypot(player.x-(police[0]?.x??1e5),player.y-(police[0]?.y??1e5))>420){player.stars=Math.max(0,player.stars-dt*.025);if(player.stars<.1){player.stars=0;police.length=0;officers.length=0}}
// reach chained mission destination while driving
if(mission<JOBS.length&&player.car&&Math.hypot(player.x-JOBS[mission].x,player.y-JOBS[mission].y)<100&&player.stars<(mission===2?1:5)){player.cash+=JOBS[mission].reward;audio.tone(820,.25);mission++;if(mission===2)crime(3);save();feedback=0.9}
for(const s of shots){s.t-=dt;s.x+=Math.cos(s.a)*760*dt;s.y+=Math.sin(s.a)*760*dt;for(const p of city.people)if(p.alive&&Math.hypot(p.x-s.x,p.y-s.y)<24){p.health-=50;s.t=0;if(p.health<=0){p.alive=false;crime(1)}else feedback=.22}}shots=shots.filter(s=>s.t>0);muzzle=Math.max(0,muzzle-dt);for(const d of dust)d.t-=dt;dust=dust.filter(d=>d.t>0);feedback=Math.max(0,feedback-dt);}
function loop(t){const dt=Math.min(.04,(t-last)/1000);last=t;update(dt,t);drawWorld(t);hud();requestAnimationFrame(loop)}
// mouse aim moves camera heading while unlocked, and can drive the scene in repeatable ?scene= shots.
window.__marisol={player,city,jobs:JOBS,get mission(){return mission},crime,toggleCar,save,advance:update};const scene=new URLSearchParams(location.search).get('scene');if(scene){player.cash=500;player.hp=100;player.stars=0;mission=0;startGame(false);if(scene==='drive'){player.car=city.cars[0];player.car.occupied=true;player.x=player.car.x=480;player.y=player.car.y=360;player.car.angle=.12;player.angle=.12;player.speed=180}else if(scene==='chase'){player.x=1180;player.y=920;player.stars=4;for(let i=0;i<4;i++)police.push({x:player.x-260-i*75,y:player.y+(i%2?150:-150),speed:0});officers.push({x:player.x-130,y:player.y+90});player.car=city.cars[1];player.car.x=player.x;player.car.y=player.y;player.car.occupied=true;player.speed=170;keys.KeyW=true}else if(scene==='mission'){mission=0;player.car=city.cars[2];player.car.x=player.x=1250;player.car.y=player.y=1000;player.car.occupied=true;JOBS[0].x=1510;JOBS[0].y=850;for(let i=0;i<4;i++){city.people[i].x=player.x+42+i*18;city.people[i].y=player.y+30;city.people[i].alive=true}shots.push({x:player.x+90,y:player.y,a:0,t:10})}requestAnimationFrame(loop)}else{start.style.display='grid';drawWorld(performance.now());hud();requestAnimationFrame(loop)}
