export function createAudio(){let context=null,muted=false,engine=null,engineGain=null,siren=null,sirenGain=null,musicTimer=0,note=0;function boot(){if(context)return;context=new AudioContext();engineGain=context.createGain();engineGain.gain.value=.035;engineGain.connect(context.destination);engine=context.createOscillator();engine.type='sawtooth';engine.frequency.value=48;const filter=context.createBiquadFilter();filter.type='lowpass';filter.frequency.value=150;engine.connect(filter);filter.connect(engineGain);engine.start();sirenGain=context.createGain();sirenGain.gain.value=0;sirenGain.connect(context.destination);siren=context.createOscillator();siren.type='triangle';siren.frequency.value=520;siren.connect(sirenGain);siren.start();const tune=[392,440,523,440,349,392,466,392];musicTimer=setInterval(()=>{if(muted||!context)return;const o=context.createOscillator(),g=context.createGain();o.type='sine';o.frequency.value=tune[note++%tune.length];g.gain.value=.014;g.connect(context.destination);o.connect(g);o.start();g.gain.exponentialRampToValueAtTime(.001,context.currentTime+.32);o.stop(context.currentTime+.34)},480)}return{start(){if(!muted)boot()},toggle(){muted=!muted;if(engineGain)engineGain.gain.value=muted?0:.035;if(sirenGain)sirenGain.gain.value=muted?0:(this.wanted?0.025:0);return muted},tone(f=440,d=.12){if(muted)return;boot();const o=context.createOscillator(),g=context.createGain();o.frequency.value=f;g.gain.setValueAtTime(.12,context.currentTime);g.gain.exponentialRampToValueAtTime(.001,context.currentTime+d);o.connect(g);g.connect(context.destination);o.start();o.stop(context.currentTime+d)},setWanted(stars){this.wanted=stars>0;if(!context||muted)return;sirenGain.gain.setTargetAtTime(stars?0.022:0,context.currentTime,.12);siren.frequency.setTargetAtTime(stars?430+(Math.sin(performance.now()/270)+1)*260:500,context.currentTime,.09)}}}
