export const WORLD={size:2400,road:104,block:300};
export function seeded(seed=43){let a=seed|0;return()=>{a=(a+0x6d2b79f5)|0;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
export function makeCity(){const r=seeded(76021),buildings=[],cars=[],people=[],lamps=[],palm=[];for(let x=120;x<2280;x+=300)for(let y=120;y<2280;y+=300){if(x>1840&&y>1650)continue;for(let i=0;i<3;i++){const bx=x+(i%2)*112-46,by=y+Math.floor(i/2)*122-45;buildings.push({x:bx,y:by,w:70+r()*38,h:72+r()*40,height:38+r()*125,color:['#d89062','#e4b779','#b87358','#d5c28e','#829b83','#c58168'][Math.floor(r()*6)]})}}for(let i=0;i<34;i++){cars.push({x:170+r()*2050,y:170+r()*2020,angle:r()*6.28,speed:0,color:['#e9bd68','#cf6649','#388694','#e7e1cf','#363f4c'][i%5],parked:i%3===0,police:false})}for(let i=0;i<60;i++)people.push({x:100+r()*2200,y:100+r()*2200,phase:r()*6.28,health:100,shirt:['#f4d08a','#b84e45','#46858a','#343f50'][i%4],alive:true});for(let x=70;x<2300;x+=180)for(let y=80;y<2300;y+=180)lamps.push({x:x+45,y:y+45});for(let x=1780;x<2300;x+=110)palm.push({x,y:140+r()*1480});return{buildings,cars,people,lamps,palm}}
